{
  "decision": "BLOCK",
  "findings": [
    {
      "severity": "high",
      "file": "cloud_pilot/multilingual/live_site.py",
      "detail": "The live-site gate treats the intersection of a supplied sitemap and manifest-declared index links as complete coverage. It does not verify the index links against captured index-page content or detect relevant live pages omitted from both inventories. A repository-absent duplicate could therefore be missed while the topic gate accepts the corpus as complete.",
      "required_fix": "Capture and hash the actual index pages, derive their links from those captures, account for pagination and other relevant URL patterns, and hold when coverage cannot be established. Add a regression where a live duplicate is absent from both the sitemap and supplied link list."
    },
    {
      "severity": "medium",
      "file": "cloud_pilot/multilingual/localize.py",
      "detail": "The multilingual path does not calculate the mandatory same-language, full-body 5-gram similarity for localized articles. Locale review and numeric checks do not replace that required writing QA.",
      "required_fix": "Run and record full-body similarity against the applicable same-language corpus for every locale, applying the manual-review and failure thresholds before delivering the multilingual bundle."
    }
  ],
  "human_reviewed": false,
  "publish_approved": false
}
